package com.voyra.crm.dto;

import io.swagger.v3.oas.annotations.media.Schema;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import lombok.Data;

/** Sizes match the platform_admin columns. The password is generated by the server. */
@Data
@Schema(description = "A new platform admin (SUPER_ADMIN) login")
public class PlatformAdminCreateRequest {

    @NotBlank(message = "Name is required")
    @Size(max = 150, message = "Name must be 150 characters or fewer")
    @Schema(example = "Priya Nair")
    private String name;

    @NotBlank(message = "Email is required")
    @Email(message = "Enter a valid email")
    @Size(max = 150, message = "Email must be 150 characters or fewer")
    @Schema(example = "priya@voyra.in")
    private String email;
}
